#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Shells;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using Tools;

namespace MVZ2.GameContent.Buffs.Entities
{
    [AutoBuffDefinition(VanillaBuffNames.Entity.bleeding)]
    public class BleedingBuff : BuffDefinition
    {
        public BleedingBuff(string nsp, string name) : base(nsp, name)
        {
        }
        public override void OnCreate(Buff buff)
        {
            base.OnCreate(buff);
            buff.SetProperty(PROP_TIMEOUT, new FrameTimer(150));
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);

            var entity = buff.GetEntity();
            var timeout = buff.GetProperty<FrameTimer>(PROP_TIMEOUT);
            if (entity == null)
                return;
            if (entity.GetShellID() != VanillaShellID.flesh)
                return;

            buff.SetProperty(PROP_TIMEOUT, timeout);
            if (timeout.RunToExpiredOrNull())
            {
                buff.Remove();
            }
            else
            {
                timeout.Run();
                if (timeout.PassedInterval(5))
                {
                    var output = entity.TakeDamage(WITHER_DAMAGE, new DamageEffectList(VanillaDamageEffects.IGNORE_ARMOR, VanillaDamageEffects.MUTE), entity);
                    if (output.BodyResult != null)
                        entity.EmitBlood();
                }
            }
        }
        public static void MaxTime(Buff buff, int frames)
        {
            var timer = buff.GetProperty<FrameTimer>(PROP_TIMEOUT);
            if (timer == null || timer.Frame >= frames)
                return;
            timer.ResetTime(frames);
        }
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_TIMEOUT = new VanillaBuffPropertyMeta<FrameTimer>("Timeout");
        public const float WITHER_DAMAGE = 2f;
    }
}
